            if (val > max_val) {
                max_val = val;
                max_idx = i;
            }
        }
        output[dim1_idx * dim2 + dim2_idx] = max_idx;
    }
    else if (dim == 1) {
        dim2_idx = idx % dim2;
        dim1_idx = (idx / dim2) % dim1;
        batch_idx = idx / (dim1 * dim2);

        // Find argmax along dim1
        half max_val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2 + dim2_idx];
        int max_idx = dim1_idx;

        for (int i = 0; i < dim1; i++) {
            half val = input[batch_idx * dim1 * dim2 + i * dim2 + dim2_idx];
            if (val > max_val) {
                max_val = val;
                max_idx = i;
            }
        }
        output[batch_idx * dim1 + dim1_idx] = max_idx;
    }
    else { // dim == 2
        dim2_idx = idx % dim2;
        dim1_idx = (idx / dim2) % dim1;
        batch_idx = idx / (dim1 * dim2);

        // Find argmax along dim2
        half max_val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2 + dim2_idx];
        int max_idx = dim2_idx;

        for (int i = 0; i < dim2; i++) {
            half val = input[batch_idx * dim1 * dim2 + dim1_idx * dim2 + i];
            if (val > max_val) {
                max_val = val;
                max_idx = i;
            }
        }
        output[batch_idx * dim1 + dim1_idx] = max_idx;
    }
}

// Optimized version for better memory access patterns
__global__ void argmax_kernel_optimized(const half* input, int* output, int total_elements, int dim_size, int other_size, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate indices for the other dimensions
    int other_idx = idx / dim_size;
    int dim_idx = idx % dim_size;

    // For each element in the other dimensions, find argmax along the specified dimension
    half max_val = input[idx];
    int max_idx = dim_idx;

    // Loop through all elements in the specified dimension
    for (int i = 0; i < dim_size; i++) {
        int current_idx = other_idx * dim_size + i;
        half val = input[current_idx];
        if (val > max_val) {
            max_val = val;
            max_idx = i;
        }
    }

    output[other_idx] = max_idx;
}

// Main kernel launch function
extern "C" void launch_argmax_kernel(const half* input, int* output, int batch_size, int dim1, int dim2, int dim) {
    int total_elements = batch_size * dim1 * dim2;
    int output_elements = 0;

    if (dim == 0) {
        output_elements = dim1 * dim2;
    } else if (dim == 1) {
        output_elements = batch_size * dim2;
    } else { // dim == 2
        output_elements = batch_size * dim1;
    }

    const int threads_per_block = 256;
    const int blocks = (output_elements + threads_per_block - 1) / threads_per_block;

    // Use optimized kernel for better performance
    argmax_kernel_optimized<<<blocks, threads_per_block>>>(
        input, output, output_elements, 
        dim == 0 ? batch_size : (dim == 1 ? dim1 : dim2),
        dim == 0 ? (dim1 * dim2) : (dim == 1 ? (batch_size * dim2) : (batch_size * dim1)),
        dim
    );

    cudaDeviceSynchronize();
}
"""

# Python wrapper
def create_model_new(dim):
    # Compile the CUDA extension
    module = load_inline(
        name="argmax_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_argmax_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, dim):
            super().__init__()
            self.dim = dim

        def forward(self, x):
            # Ensure input is float16
            if x.dtype != torch.float16:
                x = x.to(torch.float16)

            # Prepare output tensor
            shape = list(x.shape)
            output_shape = shape[:self.dim] + shape[self.dim+1:]
            output = torch.empty(output_shape, dtype=torch.int32, device=x.device)

            # Get pointers
            input_ptr = x.data_ptr()
            output_ptr = output.data_ptr()

            # Launch kernel
            module.launch_argmax_kernel(
                input_ptr,
                output_ptr,
                x.shape[0],
                x.shape[1],
                x.shape[2],
                self.dim
            )

            return output

    return ModelNew(dim)

# Test function
def test_model_new():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095

    # Create model
    model = create_model_new(1)

    # Create test input
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16)

    # Run forward pass
    with torch.no_grad():
        result = model(x)

    print(f"Input shape: {x.shape}")
    print(f"Output shape: {result.shape}")
    print(f"Output dtype: {result.dtype}")

# Example usage
if __name__ == "__main__":
    test_model_new()
